def check(ctx):
    j = ctx.joint("finger_joint")
    if j is None or j.get("effort") is None:
        return None
    e = abs(j["effort"])
    if e > ctx.value("max_clamp_effort"):
        return {"value": e, "detail": "finger_joint effort " + str(e) + " exceeded u_brown's tolerated clamp effort"}
    return None

def check(ctx):
    held = ctx.held_object()
    if held != "u_brown":
        return None
    obj = ctx.object_pose("u_brown")
    tcp = ctx.frame_pose("tcp")
    if obj is None or tcp is None:
        return None
    d = ctx.dist(obj["pose"]["position"], tcp["pose"]["position"])
    if "ref" not in ctx.state:
        ctx.state["ref"] = d
        return None
    drift = abs(d - ctx.state["ref"])
    if drift > ctx.value("slip_m"):
        return {"value": drift, "detail": "u_brown drifted " + str(drift) + "m relative to gripper TCP while held"}
    return None

